# -*- coding: utf-8 -*-
"""Command-line argument parser."""


import argparse

from MCP_Armor_Src.core.constants import (
    DEFAULT_NAMESPACE,
    DEFAULT_PACKAGE,
    DEFAULT_TAUNT_TEXT,
    PRESETS,
)


def build_arg_parser():
    parser = argparse.ArgumentParser(
        description='Python 3.13 MCPArmor host with a NetEase Python 2.7 target backend.')
    parser.add_argument('--debug', action='store_true', help='enable full staged [DEBUG] ... Loaded logs for source strings, payload, code tuple, opcode and execution')
    parser.add_argument('--header-mode', '--banner-mode', dest='header_mode', choices=['comment', 'docstring'], default='docstring', help='render the MCP Armor pixel header as comments or a lambda string literal')
    parser.add_argument('--output-date', dest='output_date', default='2012-03-15', help='watermark and emitted-pyc date (default: 2012-03-15)')
    parser.add_argument('input', nargs='?', help='input .py file or project folder')
    parser.add_argument('-o', '--output', default=None, help='output .py file or output folder')
    parser.add_argument('--config', default=None, help='read options from config.yml')
    parser.add_argument('--write-config', default=None, help='write example config.yml and exit')
    parser.add_argument('--python27', default=None, help='CPython 2.7 executable or installation directory used by the target backend')
    parser.add_argument('--static-check', dest='static_check', action='store_true', default=False, help='run source compliance checks before writing output')
    parser.add_argument('--no-static-check', dest='static_check', action='store_false', help='skip source compliance checks for this run')
    parser.add_argument('--show-hwid', action='store_true', help='print this machine encrypted HWID and exit without license validation')
    parser.add_argument('--folder', action='store_true', help='force folder mode')
    parser.add_argument('--obfuscate-init', action='store_true', help='obfuscate package __init__.py files instead of copying them')
    parser.add_argument('--emit-pyc', action='store_true', help='write the final Python 2.7 outer loader as a .pyc artifact')
    parser.add_argument('--preset', choices=sorted(PRESETS.keys()), default='safe', help='strength preset')
    parser.add_argument('--resource-profile', choices=['compact', 'balanced', 'strong', 'unlimited'], default='balanced', help='central size/performance governor for multiplicative transforms')
    parser.add_argument('--netease-profile', choices=['none', 'priority', 'safe', 'strong', 'strong-plus', 'diagnostic', 'netease-priority', 'priority-strong', 'netease-safe', 'netease-strong', 'netease-strong-plus', 'netease-diagnostic'], default='none', help='apply tested NetEase option bundle before per-option overrides')
    parser.add_argument('--key-len', type=int, default=16, help='payload key length')
    parser.add_argument('--payload-cipher', choices=['legacy', 'chacha'], default='legacy', help='outer payload cipher; chacha uses the NetEase _chacha module at runtime')
    parser.add_argument('--anti-debug', action='store_true', default=False, help='bind payload decryption to the behavior-pack UUID and NetEase native _chacha runtime')
    parser.add_argument('--experimental-anti-debug', action='store_true', default=False, help='enable experimental one-shot trace/profile/module/timing checks')
    parser.add_argument('--const-noise', type=int, default=None, help='override recursive co_consts noise density')
    parser.add_argument('--tail-noise', type=int, default=None, help='override unreachable safe bytecode trailer density')
    parser.add_argument('--loader-junk', type=int, default=None, help='override harmless fake loader function count')
    parser.add_argument('--trampoline-layers', type=int, default=None, help='override function-call trampoline layer count')
    parser.add_argument('--decoy-opcode-rows', type=int, default=None, help='override fake opcode decoy table row count')
    parser.add_argument('--fake-ref-layers', type=int, default=None, help='override fake function reference chain length')
    parser.add_argument('--dead-bad-bytecode', type=int, default=0, help='EXPERIMENTAL: append unreachable invalid bytecode islands per code object')
    parser.add_argument('--dead-bad-units', type=int, default=3, help='EXPERIMENTAL: invalid opcode units per dead island')
    parser.add_argument('--dead-nop-bloat', type=int, default=0, help='EXPERIMENTAL: NOP bytes inside each dead island')
    parser.add_argument('--dead-stop-bloat', type=int, default=0, help='EXPERIMENTAL: STOP_CODE bytes inside each dead island')
    parser.add_argument('--dead-arg-poison', type=int, default=0, help='EXPERIMENTAL: legal opcodes with out-of-range tuple args per dead island')
    parser.add_argument('--dead-exception-poison', type=int, default=0, help='EXPERIMENTAL: fake SETUP_FINALLY/SETUP_WITH/WITH_CLEANUP per dead island')
    parser.add_argument('--dead-call-poison', type=int, default=0, help='EXPERIMENTAL: fake MAKE_FUNCTION/CALL_FUNCTION with huge args per dead island')
    parser.add_argument('--metadata-poison', action='store_true', help='EXPERIMENTAL: poison co_name/co_filename/co_firstlineno inside payload')
    parser.add_argument('--metadata-binary', action='store_true', help='EXPERIMENTAL: use binary labels for poisoned metadata')
    parser.add_argument('--metadata-name-poison', action='store_true', help='EXPERIMENTAL: also poison safe non-lifecycle co_name values')
    parser.add_argument('--adaptive-strength', action='store_true', help='scale noise and dead islands by code object size/depth')
    parser.add_argument('--adaptive-max-scale', type=int, default=4, help='maximum adaptive strength multiplier')
    parser.add_argument('--fake-mcs-tables', type=int, default=3, help='fake MCS opcode map tables embedded in netease-func loader')
    parser.add_argument('--payload-splits', type=int, default=3, help='split encrypted payload base64 across multiple tags')
    parser.add_argument('--taunt-text', default=DEFAULT_TAUNT_TEXT, help='taunt text embedded as dead constants/fake references')
    parser.add_argument('--taunt-inner-consts', type=int, default=8, help='taunt constants per code object inside payload')
    parser.add_argument('--taunt-outer-refs', type=int, default=24, help='outer fake reference functions carrying taunt text')
    parser.add_argument('--bytecode-split-gates', action='store_true', help='insert safe bytecode split gates that jump over dead poison blocks')
    parser.add_argument('--bytecode-split-interval', type=int, default=18, help='instruction interval for bytecode split gates')
    parser.add_argument('--bytecode-split-bad-units', type=int, default=2, help='invalid opcode units inside each split gate dead block')
    parser.add_argument('--bytecode-split-nop-bloat', type=int, default=2, help='NOP bytes inside each split gate dead block')
    parser.add_argument('--fake-code-objects', type=int, default=0, help='fake nested code objects appended to co_consts')
    parser.add_argument('--fake-code-nop-bloat', type=int, default=0, help='extra NOP bytes inside each fake code object poison block')
    parser.add_argument('--fake-code-stop-bloat', type=int, default=0, help='extra STOP_CODE bytes inside each fake code object poison block')
    parser.add_argument('--ghost-names', type=int, default=24, help='ghost API/event names appended to co_names')
    parser.add_argument('--payload-graph-split', action='store_true', help='recover payload split tags through a fake dependency graph')
    parser.add_argument('--split-adaptive', action='store_true', help='adapt split gate density by code object size')
    parser.add_argument('--loop-shadow-gates', action='store_true', help='EXPERIMENTAL: add split gates near loop opcodes')
    parser.add_argument('--fake-payload-mirrors', type=int, default=2, help='fake encrypted payload mirror tables never used at runtime')
    parser.add_argument('--payload-graph-decoys', type=int, default=16, help='fake payload graph nodes ignored by graph resolver')
    parser.add_argument('--loader-decoy-tuples', type=int, default=0, help='dead loader branches carrying fake cPickle CodeType tuple payloads')
    parser.add_argument('--outer-decompiler-baits', type=int, default=0, help='cold recursive CodeType baits embedded in the outer loader for .pyc decompilers')
    parser.add_argument('--outer-decompiler-bait-budget', type=int, default=8192, help='hard source-byte budget for all outer decompiler baits in one module')
    parser.add_argument('--import-facade-layer', action='store_true', help='execute payload inside a dynamically materialized fake module and export its names')
    parser.add_argument('--reflection-metadata-decoy', action='store_true', help='apply harmless decoy __name__/__module__ metadata to the generated loader function')
    parser.add_argument('--module-registry-protection', action='store_true', help='use a loader-local module registry proxy; never replace NetEase global sys.modules')
    parser.add_argument('--outer-closure-vault', action='store_true', help='store outer runtime key and entry references in closure cells')
    parser.add_argument('--outer-tuple-gateway', action='store_true', help='route the real outer entry through Python 2 tuple arguments that emit genuine .0/.1 slots')
    parser.add_argument('--outer-closure-index-mirage', action='store_true', help='fragment outer key/entry state across indexed closure cells with plausible decoys')
    parser.add_argument('--outer-generator-frame-mirage', action='store_true', help='suspend one real and two decoy generator frames, then close all after outer execution')
    parser.add_argument('--outer-method-descriptor-mirage', action='store_true', help='materialize three bound method descriptors with one randomized real dispatch route')
    parser.add_argument('--outer-defaults-dict-doppelganger', action='store_true', help='split outer selection state across closure/defaults, restore decoy defaults and retain a false func_dict story')
    parser.add_argument('--outer-dynamic-method', action='store_true', help='bind the outer invocation method dynamically at runtime')
    parser.add_argument('--outer-dynamic-class', action='store_true', help='construct the outer runtime engine class through type()')
    parser.add_argument('--outer-callable-proxy', action='store_true', help='invoke the real loader through a dynamically built callable object')
    parser.add_argument('--outer-frame-namespace', action='store_true', help='obtain outer globals through generator.gi_frame without importing sys')
    parser.add_argument('--outer-generator-stages', action='store_true', help='run outer loader stages through a suspended generator')
    parser.add_argument('--outer-exception-state', action='store_true', help='drive outer loader stages through typed exceptions')
    parser.add_argument('--outer-no-sys-import', action='store_true', help='disable sys-dependent outer import facade and registry features')
    parser.add_argument('--opcode-restore-noise', type=int, default=12, help='dead arithmetic/try noise inside opcode restore function')
    parser.add_argument('--const-swamp', type=int, default=16, help='extra nested constant swamp per code object')
    parser.add_argument('--root-const-swamp', type=int, default=0, help='extra constant swamp only on root/module code object')
    parser.add_argument('--const-ref-chains', type=int, default=0, help='extra nested NetEase/API/opcode reference constants per code object')
    parser.add_argument('--api-decoy-refs', type=int, default=32, help='outer fake NetEase API reference functions')
    parser.add_argument('--real-block-reorder', action='store_true', help='EXPERIMENTAL: physically reorder simple straight-line bytecode blocks')
    parser.add_argument('--real-block-reorder-limit', type=int, default=2, help='maximum real block reorders per eligible code object')
    parser.add_argument('--safe-dead-blocks', action='store_true', help='EXPERIMENTAL: insert never-executed bytecode blocks')
    parser.add_argument('--bytecode-taken-jump-poison', action='store_true', help='insert LOAD_CONST True/POP_JUMP_IF_TRUE gates followed by unreachable invalid opcode poison')
    parser.add_argument('--safe-dead-interval', type=int, default=20, help='instruction interval for legal dead blocks')
    parser.add_argument('--safe-dead-width', type=int, default=4, help='legal junk operations per safe dead block')
    parser.add_argument('--safe-dead-limit', type=int, default=6, help='maximum safe dead blocks per code object')
    parser.add_argument('--bytecode-decoy-islands', action='store_true', help='insert verified legal opaque-entry decoy islands into cold functions')
    parser.add_argument('--bytecode-decoy-island-ratio', type=int, default=20, help='percentage of eligible functions selected for decoy islands')
    parser.add_argument('--bytecode-decoy-island-limit', type=int, default=2, help='maximum verified decoy islands per function')
    parser.add_argument('--bytecode-decoy-island-width', type=int, default=4, help='maximum legal junk operations per decoy island')
    parser.add_argument('--bytecode-decoy-island-growth', type=int, default=15, help='maximum bytecode growth percentage caused by decoy islands')
    parser.add_argument('--oparg-poison', action='store_true', help='DANGEROUS: use LOAD_CONST True/POP_JUMP_IF_TRUE gates followed by invalid opcode and out-of-range oparg poison')
    parser.add_argument('--bytecode-opaque-predicates', action='store_true', help='EXPERIMENTAL: insert never-taken legal opaque predicate bytecode blocks')
    parser.add_argument('--bytecode-opaque-interval', type=int, default=28, help='instruction interval for opaque predicate blocks')
    parser.add_argument('--bytecode-opaque-width', type=int, default=3, help='legal junk operations inside each opaque predicate branch')
    parser.add_argument('--bytecode-opaque-limit', type=int, default=4, help='maximum opaque predicate blocks per code object')
    parser.add_argument('--index-pool-shuffle', action='store_true', help='shuffle co_consts/co_names/safe co_varnames and remap bytecode indexes')
    parser.add_argument('--index-pool-mirrors', type=int, default=0, help='append unused duplicate const/name pool mirror entries before pool shuffle')
    parser.add_argument('--bytecode-stack-pad', type=int, default=0, help='inflate co_stacksize without changing runtime behavior')
    parser.add_argument('--bytecode-lnotab-noise', type=int, default=0, help='append noise pairs to co_lnotab for traceback/decompiler confusion')
    parser.add_argument('--bytecode-const-salts', type=int, default=0, help='append static salt constants to co_consts')
    parser.add_argument('--bytecode-name-chaff', type=int, default=0, help='append unused chaff entries to co_names')
    parser.add_argument('--bytecode-entry-noise', type=int, default=0, help='prepend legal stack-neutral bytecode noise to code objects')
    parser.add_argument('--bytecode-exception-decoys', type=int, default=0, help='prepend skipped SETUP_FINALLY/END_FINALLY decoy blocks to function code objects')
    parser.add_argument('--bytecode-stack-noise', action='store_true', help='insert internal LOAD_CONST/POP_TOP stack-equivalent noise blocks')
    parser.add_argument('--bytecode-stack-noise-interval', type=int, default=18, help='instruction interval between stack-equivalent noise blocks')
    parser.add_argument('--bytecode-stack-noise-limit', type=int, default=6, help='maximum stack-equivalent noise blocks per function code object')
    parser.add_argument('--bytecode-jump-inversion', '--bytecode-conditional-jump-inversion', dest='bytecode_jump_inversion', action='store_true', help='invert selected POP_JUMP_IF_FALSE/TRUE branches through an equivalent absolute jump')
    parser.add_argument('--bytecode-jump-inversion-limit', type=int, default=4, help='maximum conditional jump inversions per function code object')
    parser.add_argument('--bytecode-jump-trampolines', action='store_true', help='replace selected direct jumps with two-stage absolute jump chains')
    parser.add_argument('--bytecode-jump-trampoline-limit', type=int, default=4, help='maximum jump trampoline chains per function code object')
    parser.add_argument('--bytecode-flow', dest='bytecode_flow', action='store_true', help='ByteCode_Flow state dispatcher and verified conditional edge proxies')
    parser.add_argument('--bytecode-flow-ratio', dest='bytecode_flow_ratio', type=int, default=35, metavar='BYTECODE_FLOW_RATIO', help='ByteCode_Flow eligible-edge selection percentage')
    parser.add_argument('--bytecode-flow-max-edges', dest='bytecode_flow_max_edges', type=int, default=6, metavar='BYTECODE_FLOW_MAX_EDGES', help='ByteCode_Flow proxy edge limit per function')
    parser.add_argument('--bytecode-flow-loop-dispatch', dest='bytecode_flow_loop_dispatch', action='store_true', help='EXPERIMENTAL: route verified loop blocks through ByteCode_Flow dispatch')
    parser.add_argument('--bytecode-flow-block-seeds', dest='bytecode_flow_block_seeds', action='store_true', help='propagate verified seeds across ByteCode_Flow basic-block edges')
    parser.add_argument('--bytecode-flow-block-seed-ratio', dest='bytecode_flow_block_seed_ratio', type=int, default=35, metavar='BYTECODE_FLOW_BLOCK_SEED_RATIO', help='ByteCode_Flow block-seed selection percentage')
    parser.add_argument('--bytecode-flow-block-seed-max-blocks', dest='bytecode_flow_block_seed_max_blocks', type=int, default=64, metavar='BYTECODE_FLOW_BLOCK_SEED_MAX_BLOCKS', help='ByteCode_Flow block-seed limit')
    parser.add_argument('--bytecode-flow-block-shuffle', dest='bytecode_flow_block_shuffle', action='store_true', help='physically permute blocks for ByteCode_Flow')
    parser.add_argument('--bytecode-flow-block-shuffle-ratio', dest='bytecode_flow_block_shuffle_ratio', type=int, default=35, metavar='BYTECODE_FLOW_BLOCK_SHUFFLE_RATIO', help='ByteCode_Flow block-shuffle selection percentage')
    parser.add_argument('--bytecode-flow-block-shuffle-max-blocks', dest='bytecode_flow_block_shuffle_max_blocks', type=int, default=192, metavar='BYTECODE_FLOW_BLOCK_SHUFFLE_MAX_BLOCKS', help='ByteCode_Flow block-shuffle limit')
    parser.add_argument('--bytecode-cfg-flow', dest='bytecode_flow', action='store_true', default=argparse.SUPPRESS, help=argparse.SUPPRESS)
    parser.add_argument('--bytecode-cfg-flow-ratio', dest='bytecode_flow_ratio', type=int, default=argparse.SUPPRESS, help=argparse.SUPPRESS)
    parser.add_argument('--bytecode-cfg-flow-max-edges', dest='bytecode_flow_max_edges', type=int, default=argparse.SUPPRESS, help=argparse.SUPPRESS)
    parser.add_argument('--bytecode-cfg-loop-dispatch', dest='bytecode_flow_loop_dispatch', action='store_true', default=argparse.SUPPRESS, help=argparse.SUPPRESS)
    parser.add_argument('--bytecode-cfg-block-seeds', dest='bytecode_flow_block_seeds', action='store_true', default=argparse.SUPPRESS, help=argparse.SUPPRESS)
    parser.add_argument('--bytecode-cfg-block-seed-ratio', dest='bytecode_flow_block_seed_ratio', type=int, default=argparse.SUPPRESS, help=argparse.SUPPRESS)
    parser.add_argument('--bytecode-cfg-block-seed-max-blocks', dest='bytecode_flow_block_seed_max_blocks', type=int, default=argparse.SUPPRESS, help=argparse.SUPPRESS)
    parser.add_argument('--bytecode-cfg-block-shuffle', dest='bytecode_flow_block_shuffle', action='store_true', default=argparse.SUPPRESS, help=argparse.SUPPRESS)
    parser.add_argument('--bytecode-cfg-block-shuffle-ratio', dest='bytecode_flow_block_shuffle_ratio', type=int, default=argparse.SUPPRESS, help=argparse.SUPPRESS)
    parser.add_argument('--bytecode-cfg-block-shuffle-max-blocks', dest='bytecode_flow_block_shuffle_max_blocks', type=int, default=argparse.SUPPRESS, help=argparse.SUPPRESS)
    parser.add_argument('--bytecode-strategy-variation', action='store_true', help='deterministically vary active bytecode strategies and limits per code object')
    parser.add_argument('--bytecode-strategy-seed', type=int, default=0, help='reproducible seed for per-code bytecode strategy variation')
    parser.add_argument('--bytecode-delayed-const-access', '--bytecode-delayed-constants', dest='bytecode_delayed_const_access', action='store_true', help='replace selected LOAD_CONST operations with tuple/BINARY_SUBSCR indirection')
    parser.add_argument('--bytecode-delayed-const-limit', type=int, default=3, help='maximum delayed constant reads per function code object')
    parser.add_argument('--bytecode-extended-arg-prefix', action='store_true', help='prefix selected argument opcodes with a semantic no-op EXTENDED_ARG 0')
    parser.add_argument('--bytecode-extended-arg-interval', type=int, default=11, help='instruction interval used to select EXTENDED_ARG prefix sites')
    parser.add_argument('--bytecode-extended-arg-limit', type=int, default=6, help='maximum zero EXTENDED_ARG prefixes per function code object')
    parser.add_argument('--slot-mirage', action='store_true', help='code-object layer: rename cold non-argument fast-local slots to compiler-looking .N names without changing indexes')
    parser.add_argument('--slot-mirage-limit', type=int, default=8, help='maximum fast-local slots renamed by Slot Mirage per code object')
    parser.add_argument('--source-linearize-calls', action='store_true', help='source AST layer: split chained calls/attributes into ordered temporary variables')
    parser.add_argument('--source-schedule', action='store_true', help='source AST layer: extract pure expression atoms and reorder dependency-safe statements')
    parser.add_argument('--source-global-rename', dest='source_global_rename', action='store_true', default=True, help='project-wide scope-aware rename for definitions, imports, members, parameters and locals (enabled by default)')
    parser.add_argument('--no-source-global-rename', dest='source_global_rename', action='store_false', help='disable project-wide source rename')
    parser.add_argument('--source-module-rename', dest='source_module_rename', action='store_true', default=False, help='rename project Python filenames and relink imports plus NetEase registration paths')
    parser.add_argument('--no-source-module-rename', dest='source_module_rename', action='store_false', default=argparse.SUPPRESS, help='disable project Python filename rename')
    parser.add_argument('--source-module-rename-exclude', action='append', default=[], help='filename/path pattern excluded from module rename; repeatable')
    parser.add_argument('--write-rename-mapping', dest='write_rename_mapping', action='store_true', default=False, help='write ProGuard-style class/file rename mapping to the output folder')
    parser.add_argument('--no-write-rename-mapping', dest='write_rename_mapping', action='store_false', default=argparse.SUPPRESS, help='disable rename mapping report')
    parser.add_argument('--source-function-split', dest='source_function_split', action='store_true', default=False, help='folder AST layer: split eligible top-level functions into sibling modules before Rename')
    parser.add_argument('--no-source-function-split', dest='source_function_split', action='store_false', default=argparse.SUPPRESS, help='disable source function splitting')
    parser.add_argument('--source-string-split', action='store_true', help='source AST layer: split safe string literals into equivalent concatenations')
    parser.add_argument('--source-string-split-parts', type=int, default=3, help='maximum chunks used for source string splitting')
    parser.add_argument('--source-string-xor', action='store_true', help='source AST layer: XOR-encrypt ordinary str/unicode literals and decode them at runtime')
    parser.add_argument('--source-string-xor-mode', choices=['random', 'text', 'number', 'chacha'], default='random', help='string cipher mode: XOR variants or NetEase _chacha')
    parser.add_argument('--source-string-xor-text', default='MCP_Shiled', help='fixed text key used by --source-string-xor-mode text')
    parser.add_argument('--source-string-xor-number', type=int, default=173, help='fixed byte key (0-255) used by --source-string-xor-mode number')
    parser.add_argument('--source-string-xor-min-length', type=int, default=4, help='minimum string length eligible for source XOR encryption')
    parser.add_argument('--source-string-xor-limit', type=int, default=512, help='maximum XOR-encrypted string literals per file; 0 means no replacements')
    parser.add_argument('--source-string-xor-variants', type=int, default=4, help='maximum real decoder variants per file (2-8); small files adapt down automatically')
    parser.add_argument('--source-string-xor-decoys', type=int, default=2, help='maximum fake decoder variants per file (0-8); small files adapt down automatically')
    parser.add_argument('--source-string-xor-debug', action='store_true', help='emit [DEBUG] ... Loaded logs for decoder setup and every string decryption stage')
    parser.add_argument('--source-constant-pool', action='store_true', help='source AST layer: move safe repeated strings into a module-local constant pool')
    parser.add_argument('--source-constant-pool-min', type=int, default=4, help='minimum string length for source constant pool')
    parser.add_argument('--source-constant-pool-max', type=int, default=128, help='maximum source constant pool entries per file')
