    parser.add_argument('--source-constant-rewrite-limit', type=int, default=8, help='maximum local constants rewritten per function')
    parser.add_argument('--source-exception-shell', action='store_true', help='source AST layer: add safe exception shells around harmless local guards')
    parser.add_argument('--source-parenthesis-noise', action='store_true', help='source AST layer: add harmless redundant parentheses during source rendering')
    parser.add_argument('--source-comment-noise', action='store_true', help='source output layer: insert harmless randomized comments between top-level statements')
    parser.add_argument('--source-comment-noise-count', type=int, default=2, help='maximum randomized comment lines per source file')
    parser.add_argument('--source-dead-flow', action='store_true', help='source AST layer: inject unreachable fake branches/pseudo control flow')
    parser.add_argument('--source-dead-flow-blocks', type=int, default=1, help='maximum source dead-flow blocks per function/class/module')
    parser.add_argument('--source-vm', action='store_true', help='source AST layer: virtualize selected safe function bodies with a randomized register machine')
    parser.add_argument('--source-vm-ir', action='store_true', help='VM-IR class: enable full-coverage IR virtualization profile')
    parser.add_argument('--source-vm-extension', action='store_true', help='VM extension class: enable the legacy selective AST VM and its carrier extensions')
    parser.add_argument('--source-vm-full', action='store_true', help='virtualize every supported non-hot function with loops and expanded size limits')
    parser.add_argument('--source-vm-ratio', type=int, default=15, help='percentage of eligible functions selected for AST VM virtualization')
    parser.add_argument('--source-vm-min-ops', type=int, default=8, help='minimum AST node count for AST VM virtualization')
